/// against the chain, not the other way round.
///
/// Anything a decision rests on comes from SingulaProtocol instead: one address
/// pinned in the client's own build, reached over an RPC the client chose, with
/// every other address read from it. These fields exist so a wallet-tier client
/// can show prices and build a mint transaction without a second round trip,
/// and for nothing else.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct NetworkInfo {
    /// EVM chain ID (421614 = Arbitrum Sepolia)
    #[prost(int64, tag = "1")]
    pub chain_id: i64,
    /// A public RPC. A hint; see the note above.
    #[prost(string, tag = "2")]
    pub rpc_url: ::prost::alloc::string::String,
    /// SubscriptionNFT contract address
    #[prost(string, tag = "3")]
    pub subscription_nft_addr: ::prost::alloc::string::String,
    /// EchoToken ERC-20 address
    #[prost(string, tag = "4")]
    pub echo_token_address: ::prost::alloc::string::String,
    /// USDC ERC-20 address
    #[prost(string, tag = "5")]
    pub usdc_token_address: ::prost::alloc::string::String,
    /// Current USDC price in wei (string to avoid overflow)
    #[prost(string, tag = "6")]
    pub price_usdc_wei: ::prost::alloc::string::String,
    /// Current Echo price in wei (string to avoid overflow)
    #[prost(string, tag = "7")]
    pub price_echo_wei: ::prost::alloc::string::String,
    /// Caller's current on-chain mint nonce (from mintNonces\[wallet\])
    #[prost(uint64, tag = "8")]
    pub mint_nonce: u64,
}
/// MintRequest asks the CP to call mintWithPermit on behalf of the client.
/// Client pre-signs:
///
/// 1. EIP-712 MintRequest intent (mint_sig)
/// 1. ERC-20 permit for token approval (permit_v/r/s)
/// 1. outer EIP-191 GasStation.relayClient meta-tx (gas_sig + gas_deadline)
///    CP is a pure forwarder — does not sign anything; GasStation pays gas
///    and accounts it against the client's per-epoch EOA budget.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct MintRequest {
    /// true = ECHO (20% off), false = USDC
    #[prost(bool, tag = "1")]
    pub pay_with_echo: bool,
    /// Client's Ethereum wallet address
    #[prost(string, tag = "2")]
    pub wallet: ::prost::alloc::string::String,
    /// Max token amount agreed to (wei, string)
    #[prost(string, tag = "3")]
    pub max_cost: ::prost::alloc::string::String,
    /// Unix timestamp — EIP-712 mint intent expiry
    #[prost(int64, tag = "4")]
    pub mint_deadline: i64,
    /// 65-byte EIP-712 MintRequest signature
    #[prost(bytes = "vec", tag = "5")]
    pub mint_sig: ::prost::alloc::vec::Vec<u8>,
    /// Unix timestamp — ERC-20 permit expiry
    #[prost(int64, tag = "6")]
    pub permit_deadline: i64,
    /// ERC-20 permit signature v
    #[prost(uint32, tag = "7")]
    pub permit_v: u32,
    /// ERC-20 permit signature r (32 bytes)
    #[prost(bytes = "vec", tag = "8")]
    pub permit_r: ::prost::alloc::vec::Vec<u8>,
    /// ERC-20 permit signature s (32 bytes)
    #[prost(bytes = "vec", tag = "9")]
    pub permit_s: ::prost::alloc::vec::Vec<u8>,
    /// Unix timestamp — relayClient meta-tx expiry
    #[prost(int64, tag = "10")]
    pub gas_deadline: i64,
    /// 65-byte EIP-191 sig over relayClient digest
    #[prost(bytes = "vec", tag = "11")]
    pub gas_sig: ::prost::alloc::vec::Vec<u8>,
    /// Concurrent sessions the Orbit pays for, 1 to 5. It costs that many times
    /// the price, and is part of what mint_sig signs.
    #[prost(uint32, tag = "12")]
    pub slots: u32,
}
/// RegisterCommitmentRequest asks the Control Plane to relay a subscriber's
/// registration into the on-chain SubscriberRegistry, so joining the anonymity
/// set costs the subscriber no gas.
///
/// The registry verifies `register_sig` itself: a Control Plane can decline to
/// relay, but cannot register a commitment the wallet did not sign for.
///
/// The wallet-to-commitment pair is public on chain once the transaction lands.
/// A membership proof never reveals which commitment it used.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct RegisterCommitmentRequest {
    /// Ethereum wallet holding the subscription
    #[prost(string, tag = "1")]
    pub wallet: ::prost::alloc::string::String,
    /// Subscription NFT being registered
    #[prost(uint64, tag = "2")]
    pub token_id: u64,
    /// EIP-712 Register intent expiry
    #[prost(int64, tag = "4")]
    pub deadline: i64,
    /// 65-byte EIP-712 Register signature
    #[prost(bytes = "vec", tag = "5")]
    pub register_sig: ::prost::alloc::vec::Vec<u8>,
    /// 32-byte Semaphore identity commitments, one per slot at most counting
    /// those already registered for this Orbit.
    #[prost(bytes = "vec", repeated, tag = "8")]
    pub commitments: ::prost::alloc::vec::Vec<::prost::alloc::vec::Vec<u8>>,
}
/// RegisterCommitmentResult is sent back once the transaction is mined.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct RegisterCommitmentResult {
    #[prost(bool, tag = "1")]
    pub success: bool,
    #[prost(string, tag = "2")]
    pub error_message: ::prost::alloc::string::String,
    #[prost(string, tag = "3")]
    pub tx_hash: ::prost::alloc::string::String,
}
/// MintResult is sent back after the mint transaction is mined.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct MintResult {
    #[prost(bool, tag = "1")]
    pub success: bool,
    /// Set if success = false
    #[prost(string, tag = "2")]
    pub error_message: ::prost::alloc::string::String,
    /// On-chain tx hash (set if success = true)
    #[prost(string, tag = "3")]
    pub tx_hash: ::prost::alloc::string::String,
    /// Minted token ID
    #[prost(uint64, tag = "4")]
    pub token_id: u64,
}
